import path from 'path';
import {
  posixPath,
  Globby,
  parseURLPath,
  serializeURLPath,
  flattenRoutes,
  normalizeUrl,
  type URLPath,
} from '@docusaurus/utils';
import {
  addTrailingSlash,
  removeTrailingSlash,
  applyTrailingSlash,
  type ApplyTrailingSlashParams,
} from '@docusaurus/utils-common';
import type {RouteConfig} from '@docusaurus/types';

export type {URLPath, ApplyTrailingSlashParams};

// Globby that fix Windows path patterns
// See https://github.com/facebook/docusaurus/pull/4222#issuecomment-795517329
export async function safeGlobby(
  patterns: string[],
  options?: Globby.GlobbyOptions,
): Promise<string[]> {
  // Required for Windows support, as paths using \ should not be used by globby
  // (also using the windows hard drive prefix like c: is not a good idea)
  const globPaths = patterns.map((dirPath) =>
    posixPath(path.relative(process.cwd(), dirPath)),
  );

  return Globby(globPaths, options);
}

export function resolvePageURLPath(
  urlPath: string,
  fromPath?: string,
): URLPath {
  return parseURLPath(urlPath, fromPath);
}

export function serializePageURLPath(urlPath: URLPath): string {
  return serializeURLPath(urlPath);
}

export function flattenLeafRoutes(routeConfig: RouteConfig[]): RouteConfig[] {
  return flattenRoutes(routeConfig);
}

export function joinUrlSegments(segments: string[]): string {
  return normalizeUrl(segments);
}

export function withTrailingSlash(pathname: string): string {
  return addTrailingSlash(pathname);
}

export function withoutTrailingSlash(pathname: string): string {
  return removeTrailingSlash(pathname);
}

export function applyPathTrailingSlash(
  pathname: string,
  options: ApplyTrailingSlashParams,
): string {
  return applyTrailingSlash(pathname, options);
}

