    await testBrokenLinks({
      routes: [{path: '/page1'}, {path: '/page2'}],
      collectedLinks: {
        '/page1': {links: ['/page2'], anchors: []},
        '/page2': {links: [], anchors: []},
      },
    });
  });

  it('accepts valid non-exact link', async () => {
    await testBrokenLinks({
      routes: [{path: '/page1', exact: false}, {path: '/page2/'}],
